// Using fixed point instead of floating point
// to improve precision at the same storage cost.

// 32 bit floats only have 23 bits of actual full
// precision, since 8 bits are used for scale. But
// if the range is known, we can get rif of it and
// free up space for the number itself, leading to
// extra precision with the same number of bits.

// I just realized ockiller's almost identical
// https://www.shadertoy.com/view/wtKSWW, although
// it contains some errors, making it less precise.

//=============================================
// fixed point math (only integer arithmetic)
//=============================================
const int kFraBits = 28;   // 1.3.28
int float2fixed(float f) { return int(round(float(1<<kFraBits)*f)); }
int add(int a, int b) { return a+b; }
int sub(int a, int b) { return a-b; }
int mul(int a, int b) // mul would be much quicker is WebGLSL supported 64 bit integers
{
    // a * b
    uint ua = uint(abs(a));
    uint ub = uint(abs(b));
    uint al = ua & 0xffffu, ah = ua >> 16;
    uint bl = ub & 0xffffu, bh = ub >> 16;
    uint k0 = al * bl;
    uint k1 = al * bh;
    uint k2 = ah * bl;
    uint k3 = ah * bh; // c = a*b = k3<<32 + (k1+k2)<<16 + k0
    uint cl = k0 + ((k1+k2)<<16);
    uint ca = (k1&0xffffu) + (k2&0xffffu) + (k0>>16);
    uint ch = k3 + (k1>>16) + (k2>>16) + (ca>>16);
    // add 1/2 bit for proper rounding
    uint sl = cl + (1u<<(kFraBits-1));
	ch += (sl<cl) ? 1u : 0u;
    cl = sl;
    // rescale (shift right)
    int r = int( (ch<<(32-kFraBits)) | (cl>>kFraBits) );
    // sign
    return (((a^b)&0x80000000)==0 )?r:-r;
}

//=============================================

int mandelbrot_float( float cx, float cy)
{
    float x = 0.0, x2 = 0.0;
    float y = 0.0, y2 = 0.0;
    float          xy = 0.0;
    for( int i = 0; i < 6000; i++ )
    {
        x  = x2 - y2 + cx;
        y  = xy + xy + cy;
        x2 = x*x;
        y2 = y*y;
        xy = x*y;
        if( x2+y2 > 4.0 ) return i;
    }
    return 0;
}

int mandelbrot_fixed( int cx, int cy)
{
    int k4 = float2fixed(4.0);
    int x = 0, x2 = 0;
    int y = 0, y2 = 0;
    int        xy = 0;
    for( int i = 0; i < 6000; i++ )
    {
        x  = add(sub(x2,y2),cx);
        y  = add(add(xy,xy),cy);
        x2 = mul(x,x);
        y2 = mul(y,y);
        xy = mul(x,y);
        if( add(x2,y2) > k4 ) return i;
    }
    return 0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2  p = (2.0*fragCoord-iResolution.xy) / iResolution.y;
    float s = (iMouse.z<0.001) ? sin(iTime*2.0)*1.8 : (2.0*iMouse.x-iResolution.x) / iResolution.y;

    const float kzoom = 1.5e-6;
    const vec2 kc = vec2(-1.190045,0.3043895);

    int n = 0;
    if( p.x>s )
    {
        float cx = kc.x + p.x*kzoom;
        float cy = kc.y + p.y*kzoom;
        n = mandelbrot_float(cx, cy);
    }
    else
    {
        int cx = add(float2fixed(kc.x), float2fixed(p.x*kzoom));
        int cy = add(float2fixed(kc.y), float2fixed(p.y*kzoom));
        n = mandelbrot_fixed(cx, cy);
    }

    // color
    float w = pow(kzoom, 0.22) * float(n) * 0.05;
    vec3 col = (n==0) ? vec3(0.0) : 0.5 + 0.5*cos(w+vec3(3.0,3.5,4.0));

    // separator
    if( abs(p.x-s)<2.0/iResolution.y) col += vec3(1.0);

    fragColor = vec4(col,1.0);
}
